local CommonType = {}

export type PlayerVo = {
	registerTime:number,-- 注册时间
	lastLoginTime:number, -- 最后登录时间
	characterId:number, -- 已选择的角色Id
	lastWildSceneVo:WildSceneVo, -- 上次进入的野外场景数据
	groudReward:boolean,-- 群组奖励
	lastClaimDailyGemTime:number,-- 每日钻石领取事件
	noobGiftPackStartTime:number,-- 新手礼包开始时间
	adRewardTimes:number, -- 领取广告奖励次数
	lastAdRewardTime:number, -- 最后一次领取广告奖励时间
	horseSkinId:number, -- 已选择的马皮肤Id
	nextResItemShopRefreshTime:number, -- 资源物品商店刷新时间

	lastSign7Time:number, -- 上次签到时间
	sign7Times:number, -- 七日签到次数

	lastSign31Time:number, -- 上次31日签到时间
	sign31Times:number, -- 31日签到次数

	lastRefreshDailyQuestsTime:number, -- 最后一次刷新每日任务时间
	dailyQuestsRecords:{DailyQuestVo}, -- 每日任务记录

	resItemShopRecord:{number}, -- 资源物品商店刷新时间
	horseSkins:{number}, -- 已拥有的马皮肤Id
	characters:{CharacterVo}, -- 已拥有的角色
	items:{number},
	gamePass:{number},
	statsDict:{number}, -- 统计数据
	achievement:{boolean}, -- 成就
	permanentUpgrades:{{number}}, -- 永久升级
	carryResItems:{number}, -- 携带资源物品

	skinOwned:{{number}}, -- 已拥有的皮肤 key:type_id
	skinEquiped:{boolean} -- 已装备的皮肤 key:type_useObjectId
}

export type CharacterVo = {
	id:number,
	lv:number,
	stats:{number}, -- 数据统计
	timeLimit:number, -- 使用时限
