	btnCallBack:(btnType:number)->(), -- 按钮回调
}

export type GuideLineVo = {
	target:BasePart,
	lifeTime:number,
}

export type TeleportLobbyToWild = {
	characterId:number,
	level:number,
	mode:number,
}

export type WildSceneVo = {
	PrivateServerId:string,
	ReservedServerAccessCode:string,
	heatbeatTime:number,
}

export type MapMarkerVo = {
	userId:number,
	nickname:string,
	position:Vector3,
}

function CommonType:CreateDefaultPlayerVo()
	local playerVo:PlayerVo = {}
	playerVo.characters = {}
	playerVo.items = {}
	playerVo.gamePass = {}
	playerVo.statsDict = {}
	playerVo.achievement = {}
	playerVo.horseSkins = {}
	playerVo.permanentUpgrades = {}
	playerVo.adRewardTimes = 0
	playerVo.lastAdRewardTime = 0
	playerVo.carryResItems = {}
	playerVo.nextResItemShopRefreshTime = 0
	playerVo.resItemShopRecord = {}
	playerVo.sign7Times = 0
	playerVo.lastSign7Time = 0
	playerVo.sign31Times = 0
	playerVo.lastSign31Time = 0

	playerVo.lastRefreshDailyQuestsTime = 0
	playerVo.dailyQuestsRecords = {}

	playerVo.skinOwned = {}
	playerVo.skinEquiped = {}

	return playerVo
end

function CommonType:CreateDefaultWildSceneVo()
	local wildSceneVo:WildSceneVo = {
        PrivateServerId = "",
        ReservedServerAccessCode = "",
        heatbeatTime = workspace:GetServerTimeNow()
    }

	return wildSceneVo
end

return CommonType

local BackpackModeHelper = {}

BackpackModeHelper.ModeEnum = {
    Legacy = "Legacy",
    GameBackpack = "GameBackpack",
}

-- Flip this value to "Legacy" to fall back to the old backpack UI.
BackpackModeHelper.Mode = BackpackModeHelper.ModeEnum.GameBackpack

function BackpackModeHelper:GetMode()
    return BackpackModeHelper.Mode
end

function BackpackModeHelper:IsLegacy()
    return BackpackModeHelper:GetMode() == BackpackModeHelper.ModeEnum.Legacy
end

function BackpackModeHelper:IsGameBackpack()
    return BackpackModeHelper:GetMode() == BackpackModeHelper.ModeEnum.GameBackpack
end

return BackpackModeHelper

return {
	ignoreUnknownInstances = true,
}

